  NS_CONTENT:'content-library',      // namespace for the tagged content library
  NS_EMPLOYEE:'employee-learning',   // namespace for assessments, learning paths, progress and feedback
  EMBED_MODEL:'text-embedding-3-small',
  OPENAI_MODEL:'gpt-5.5',            // check the exact model ID in your OpenAI account
  ADMIN_KEY:'odie8SqhbXF22xVtoy1EaDL6KZFTGJmpHpq3NRp050A',             // required by the ingest_library action (Admin tab in the app)
  TOP_K:40,                          // content items retrieved from Pinecone per assessment
  DEFAULT_WEEKLY_HOURS:4,
  MAX_ROWS:400                       // safety limit when falling back to the full CSV catalog
