const body=$input.first().json.body||{};
const f=body.form||{};
const action=String(body.action||'assess').trim().toLowerCase();
const emp_id=String(f.employee_id||body.employee_id||'').trim().toUpperCase();
const emp_name=String(f.employee_name||body.employee_name||'').trim();
