const ROUTES={ingest_library:0,verify_certificate:1,assess:2,status:2,progress:2,feedback:2};
let route=ROUTES[action],error='';
let updates=Array.isArray(body.updates)?body.updates:(body.content_id?[{content_id:body.content_id,done:body.done!==false}]:[]);
updates=updates.filter(u=>u&&u.content_id).map(u=>({content_id:String(u.content_id).trim().toUpperCase(),done:u.done!==false&&u.done!=='false'}));
const rating=parseInt(body.rating);
if(route===undefined){route=3;error='Unknown action "'+action+'". Use assess, status, progress, feedback, verify_certificate or ingest_library.';}
else if(route===0&&String(body.admin_key||'')!==CFG.ADMIN_KEY){route=3;error='Invalid admin key.';}
else if(route===1&&!String(body.cert_id||'').trim()){route=3;error='cert_id is required.';}
else if(route===2&&(!emp_id||!emp_name)){route=3;error='Employee ID and Employee Name are required.';}
else if(action==='progress'&&!updates.length){route=3;error='No progress updates supplied.';}
else if(action==='feedback'&&!(rating>=1&&rating<=5)&&!String(body.comment||'').trim()){route=3;error='Give a rating (1-5) or a comment.';}
if(action==='assess'&&route===2){
  const miss=['current_skill','career_goal','target_skill','learning_style'].filter(k=>!String(f[k]||'').trim());
  if(miss.length){route=3;error='Missing form fields: '+miss.join(', ');}
}
return [{json:{action,route,error,emp_id,emp_name,slack_user_id,updates,
  rating:rating>=1&&rating<=5?rating:null,comment:String(body.comment||'').trim().slice(0,2000),source:String(body.source||'app'),
