const HELP='*Learning Path bot* 📚\n• `/learn link EMP0001 Your Name` - connect your Slack account (once)\n• `/learn status` - progress, badges and what is next\n• `/learn done C0003` - mark content complete (`undo C0003` to revert)\n• `/learn feedback 4 too fast-paced` - rate 1-5 and comment\nMilestones: 🥉 25% · 🥈 50% · 🥇 75% · 🎓 100% certificate';
const reply=t=>[{json:{route:2,response_url:S.response_url,reply:{response_type:'ephemeral',replace_original:false,text:t}}}];
if(S.cmd==='help')return reply(HELP);
if(S.cmd==='link')return e.emp_id?[{json:{route:1,response_url:S.response_url,emp_id:e.emp_id,emp_name:e.emp_name,slack_user_id:S.slack_user_id}}]
