let api;
if(S.cmd==='status')api={action:'status',...base};
else if(S.cmd==='done'||S.cmd==='undo'){const ids=S.args.filter(a=>/^[A-Za-z]+\d+$/.test(a));
  if(!ids.length)return reply('Tell me which content: `/learn '+S.cmd+' C0003` (IDs are listed in `/learn status`).');
  api={action:'progress',...base,updates:ids.map(id=>({content_id:id,done:S.cmd==='done'}))};}
else if(S.cmd==='feedback'){const n=parseInt(S.args[0]);const has=n>=1&&n<=5;
  api={action:'feedback',...base,rating:has?n:null,comment:(has?S.args.slice(1):S.args).join(' ')};
