const R=$('Slack Route').first().json,d=$input.first().json||{},S=$('Parse Slack Request').first().json;
const bar=x=>{const n=Math.round((x||0)/10);return '█'.repeat(n)+'░'.repeat(10-n)+' '+(x||0)+'%';};
const out=(text,blocks)=>[{json:{response_url:R.response_url,reply:{response_type:'ephemeral',replace_original:false,text,...(blocks?{blocks}:{})}}}];
if(d.status==='error'||d.error)return out('❌ '+(d.message||(d.error&&d.error.message)||'Something went wrong.'));
