  else if(ch==='"')q=true;else if(ch===','){r.push(v);v='';}
  else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&t[i+1]==='\n')i++;r.push(v);v='';rows.push(r);r=[];}
